import { useEffect, useMemo, useState } from "react";
import {
  Badge,
  Button,
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
  Kbd,
  Progress,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@databricks/appkit-ui/react";
import { Pause, Play, RotateCcw, Trophy } from "lucide-react";

import {
  BOARD_COLS,
  BOARD_ROWS,
  PIECE_SHAPES,
  PIECE_COLORS,
  sampleBoard,
  currentPiece,
  nextPieces,
  gameStats,
  gameStatus,
  controls,
  leaderboard,
  scoreRules,
  levelSpeeds,
} from "../mock";
import type { PieceType, GameStatus } from "../mock";

const colorClass = (t: PieceType | null): string => {
  if (!t) return "bg-muted/40";
  const map: Record<PieceType, string> = {
    I: "bg-chart-1",
    O: "bg-chart-2",
    T: "bg-chart-3",
    S: "bg-chart-4",
    Z: "bg-destructive",
    J: "bg-chart-5",
    L: "bg-primary",
  };
  return map[t] ?? PIECE_COLORS[t];
};

function MiniPiece({ type }: { type: PieceType }) {
  const shape = PIECE_SHAPES[type];
  return (
    <div className="inline-grid gap-0.5" style={{ gridTemplateColumns: `repeat(${shape[0].length}, 1fr)` }}>
      {shape.flatMap((row, r) =>
        row.map((v, c) => (
          <div key={`${r}-${c}`} className={`size-4 rounded-sm ${v ? colorClass(type) : "bg-transparent"}`} />
        )),
      )}
    </div>
  );
}

export default function Tetris() {
  const [status, setStatus] = useState<GameStatus>(gameStatus);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key.toLowerCase() === "p") {
        setStatus((s) => (s === "playing" ? "paused" : s === "paused" || s === "idle" ? "playing" : s));
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, []);

  const board = useMemo(() => {
    const b = sampleBoard.map((r) => [...r]);
    const shape = PIECE_SHAPES[currentPiece.type];
    shape.forEach((row, r) =>
      row.forEach((v, c) => {
        const y = currentPiece.y + r;
        const x = currentPiece.x + c;
        if (v && y >= 0 && y < BOARD_ROWS && x >= 0 && x < BOARD_COLS) b[y][x] = currentPiece.type;
      }),
    );
    return b;
  }, []);

  const levelProgress = (gameStats.lines % 10) * 10;
  const speed = levelSpeeds.find((l) => l.level === gameStats.level);

  return (
    <div className="mx-auto max-w-6xl space-y-16 p-8 md:p-12">
      <header className="flex flex-wrap items-end justify-between gap-6">
        <div>
          <p className="text-sm font-medium uppercase tracking-widest text-primary">Arcade</p>
          <h1 className="text-5xl font-bold tracking-tight">Tetris</h1>
        </div>
        <div className="text-right">
          <p className="text-sm text-muted-foreground">High score</p>
          <p className="flex items-center justify-end gap-2 text-2xl font-semibold tabular-nums">
            <Trophy className="size-5 text-warning" />
            {gameStats.highScore.toLocaleString()}
          </p>
        </div>
      </header>

      <section className="grid items-start gap-10 lg:grid-cols-[1fr_auto_1fr]">
        <div className="space-y-8">
          <div>
            <p className="text-sm uppercase tracking-widest text-muted-foreground">Score</p>
            <p className="text-6xl font-bold tabular-nums">{gameStats.score.toLocaleString()}</p>
          </div>
          <div className="grid grid-cols-2 gap-6">
            <div>
              <p className="text-sm text-muted-foreground">Level</p>
              <p className="text-3xl font-semibold tabular-nums">{gameStats.level}</p>
            </div>
            <div>
              <p className="text-sm text-muted-foreground">Lines</p>
              <p className="text-3xl font-semibold tabular-nums">{gameStats.lines}</p>
            </div>
          </div>
          <div className="space-y-2">
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Next level</span>
              <span>{speed ? `${speed.dropMs} ms/drop` : ""}</span>
            </div>
            <Progress value={levelProgress} />
          </div>
        </div>

        <div className="relative mx-auto rounded-xl border bg-card p-3 shadow-lg">
          <div
            className="grid gap-0.5"
            style={{ gridTemplateColumns: `repeat(${BOARD_COLS}, 1fr)` }}
          >
            {board.flatMap((row, r) =>
              row.map((cell, c) => (
                <div key={`${r}-${c}`} className={`size-6 rounded-sm sm:size-7 ${colorClass(cell)}`} />
              )),
            )}
          </div>
          {status !== "playing" && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-4 rounded-xl bg-background/80 backdrop-blur-sm">
              <Badge variant="secondary" className="uppercase">
                {status === "paused" ? "Paused" : status === "gameover" ? "Game over" : "Ready"}
              </Badge>
              <Button size="lg" onClick={() => setStatus("playing")}>
                <Play /> {status === "paused" ? "Resume" : "Start"}
              </Button>
            </div>
          )}
        </div>

        <div className="space-y-8">
          <Card>
            <CardHeader>
              <CardDescription>Next</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              {nextPieces.slice(0, 3).map((p, i) => (
                <div key={i} className={`flex h-14 items-center ${i === 0 ? "" : "opacity-50"}`}>
                  <MiniPiece type={p} />
                </div>
              ))}
            </CardContent>
          </Card>
          <div className="flex gap-2">
            <Button
              variant="outline"
              className="flex-1"
              onClick={() => setStatus((s) => (s === "playing" ? "paused" : "playing"))}
            >
              {status === "playing" ? <Pause /> : <Play />}
              {status === "playing" ? "Pause" : "Play"} <Kbd>P</Kbd>
            </Button>
            <Button variant="ghost" size="icon" onClick={() => setStatus("idle")}>
              <RotateCcw />
            </Button>
          </div>
        </div>
      </section>

      <section className="grid gap-8 lg:grid-cols-3">
        <Card>
          <CardHeader>
            <CardTitle>Controls</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {controls.map((c) => (
              <div key={c.action} className="flex items-center justify-between gap-4 text-sm">
                <span className="text-muted-foreground">{c.description}</span>
                <span className="flex gap-1">
                  {c.keys.map((k) => (
                    <Kbd key={k}>{k}</Kbd>
                  ))}
                </span>
              </div>
            ))}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Scoring</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {scoreRules.map((s) => (
              <div key={s.lines} className="flex justify-between text-sm">
                <span className="text-muted-foreground">{s.label}</span>
                <span className="font-medium tabular-nums">{s.points} × level</span>
              </div>
            ))}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Leaderboard</CardTitle>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>#</TableHead>
                  <TableHead>Player</TableHead>
                  <TableHead className="text-right">Score</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {leaderboard.slice(0, 5).map((e) => (
                  <TableRow key={e.rank}>
                    <TableCell>{e.rank}</TableCell>
                    <TableCell className="font-medium">{e.player}</TableCell>
                    <TableCell className="text-right tabular-nums">{e.score.toLocaleString()}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      </section>
    </div>
  );
}

