import {
  Badge,
  Button,
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  Kbd,
  Progress,
  Separator,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
  Tabs,
  TabsContent,
  TabsList,
  TabsTrigger,
  AreaChart,
} from "@databricks/appkit-ui/react";
import { Pause, Play, RotateCcw, Trophy } from "lucide-react";
import { useState } from "react";

import {
  BOARD_COLS,
  BOARD_ROWS,
  PIECE_SHAPES,
  controls,
  currentPiece,
  gameStats,
  gameStatus,
  heldPiece,
  leaderboard,
  levelSpeeds,
  nextPieces,
  sampleBoard,
  scoreHistory,
  scoreRules,
} from "../mock";
import type { GameStatus, PieceType } from "../mock";

const pieceClass: Record<PieceType, string> = {
  I: "bg-chart-1",
  O: "bg-chart-2",
  T: "bg-chart-3",
  S: "bg-chart-4",
  Z: "bg-destructive",
  J: "bg-chart-5",
  L: "bg-warning",
};

function rotate(m: number[][], times: number): number[][] {
  let r = m;
  for (let i = 0; i < ((times % 4) + 4) % 4; i++) {
    r = r[0].map((_, c) => r.map((row) => row[c]).reverse());
  }
  return r;
}

function MiniPiece({ type }: { type: PieceType | null }) {
  if (!type) {
    return (
      <div className="flex h-16 items-center justify-center text-xs text-muted-foreground">
        Empty
      </div>
    );
  }
  const shape = PIECE_SHAPES[type];
  return (
    <div className="flex h-16 items-center justify-center">
      <div className="grid gap-0.5" style={{ gridTemplateColumns: `repeat(${shape[0].length}, 1rem)` }}>
        {shape.flat().map((v, i) => (
          <div key={i} className={`size-4 rounded-sm ${v ? pieceClass[type] : ""}`} />
        ))}
      </div>
    </div>
  );
}

export default function Tetris() {
  const [status, setStatus] = useState<GameStatus>(gameStatus);

  const grid: (PieceType | null)[][] = sampleBoard.map((row) => [...row]);
  const shape = rotate(PIECE_SHAPES[currentPiece.type], currentPiece.rotation);
  shape.forEach((row, dy) =>
    row.forEach((v, dx) => {
      const y = currentPiece.y + dy;
      const x = currentPiece.x + dx;
      if (v && y >= 0 && y < BOARD_ROWS && x >= 0 && x < BOARD_COLS) {
        grid[y][x] = currentPiece.type;
      }
    }),
  );

  const speed = levelSpeeds.find((l) => l.level === gameStats.level);
  const toNext = (gameStats.lines % 10) * 10;

  const toggle = () => setStatus(status === "playing" ? "paused" : "playing");

  return (
    <div className="mx-auto max-w-6xl p-4">
      <header className="mb-4 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <h1 className="text-lg font-semibold tracking-tight">Tetris</h1>
          <Badge variant={status === "playing" ? "default" : "secondary"}>{status}</Badge>
        </div>
        <div className="flex gap-2">
          <Button size="sm" onClick={toggle}>
            {status === "playing" ? <Pause /> : <Play />}
            {status === "playing" ? "Pause" : "Play"}
          </Button>
          <Button size="sm" variant="outline" onClick={() => setStatus("idle")}>
            <RotateCcw /> Restart
          </Button>
        </div>
      </header>

      <div className="grid gap-4 md:grid-cols-[200px_auto_1fr]">
        <aside className="space-y-4">
          <Card>
            <CardHeader><CardTitle className="text-sm">Hold</CardTitle></CardHeader>
            <CardContent><MiniPiece type={heldPiece} /></CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="text-sm">Next</CardTitle></CardHeader>
            <CardContent className="space-y-1">
              {nextPieces.slice(0, 3).map((p, i) => (
                <div key={i} className={i > 0 ? "opacity-60" : ""}>
                  <MiniPiece type={p} />
                </div>
              ))}
            </CardContent>
          </Card>
        </aside>

        <div className="relative w-fit">
          <div
            className="grid gap-px rounded-md border bg-border p-px"
            style={{ gridTemplateColumns: `repeat(${BOARD_COLS}, 1.6rem)` }}
          >
            {grid.flat().map((c, i) => (
              <div key={i} className={`size-[1.6rem] ${c ? pieceClass[c] : "bg-card"}`} />
            ))}
          </div>
          {status !== "playing" && (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-2 rounded-md bg-background/80">
              <div className="text-lg font-semibold capitalize">{status === "idle" ? "Ready" : status}</div>
              <Button size="sm" onClick={toggle}><Play /> {status === "paused" ? "Resume" : "Start"}</Button>
              <span className="text-xs text-muted-foreground">or press <Kbd>P</Kbd></span>
            </div>
          )}
        </div>

        <section className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            {[
              ["Score", gameStats.score.toLocaleString()],
              ["Level", String(gameStats.level)],
              ["Lines", String(gameStats.lines)],
              ["Best", gameStats.highScore.toLocaleString()],
            ].map(([k, v]) => (
              <Card key={k}>
                <CardContent className="pt-4">
                  <div className="text-xs text-muted-foreground">{k}</div>
                  <div className="text-2xl font-semibold tabular-nums">{v}</div>
                </CardContent>
              </Card>
            ))}
          </div>
          <div className="space-y-1">
            <div className="flex justify-between text-xs text-muted-foreground">
              <span>Next level</span>
              <span>{speed ? `${speed.dropMs} ms/drop` : ""}</span>
            </div>
            <Progress value={toNext} />
          </div>
          <Separator />
          <Tabs defaultValue="controls">
            <TabsList>
              <TabsTrigger value="controls">Controls</TabsTrigger>
              <TabsTrigger value="scores">Scores</TabsTrigger>
              <TabsTrigger value="rules">Rules</TabsTrigger>
            </TabsList>
            <TabsContent value="controls">
              <Table>
                <TableBody>
                  {controls.map((c) => (
                    <TableRow key={c.action}>
                      <TableCell className="font-medium">{c.action}</TableCell>
                      <TableCell className="space-x-1">
                        {c.keys.map((k) => <Kbd key={k}>{k}</Kbd>)}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TabsContent>
            <TabsContent value="scores">
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead><Trophy className="size-4" /></TableHead>
                    <TableHead>Player</TableHead>
                    <TableHead className="text-right">Score</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {leaderboard.slice(0, 5).map((e) => (
                    <TableRow key={e.rank}>
                      <TableCell>{e.rank}</TableCell>
                      <TableCell>{e.player}</TableCell>
                      <TableCell className="text-right tabular-nums">{e.score.toLocaleString()}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
              <AreaChart data={scoreHistory} xKey="game" yKey="score" height={160} />
            </TabsContent>
            <TabsContent value="rules">
              <Table>
                <TableBody>
                  {scoreRules.map((r) => (
                    <TableRow key={r.lines}>
                      <TableCell>{r.label}</TableCell>
                      <TableCell className="text-right tabular-nums">{r.points}</TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TabsContent>
          </Tabs>
        </section>
